INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (20001, 0, 320, 10, "", 0, "", 23001, 2, 0, 20);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 1, 321, 1, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 0, "リリ", 24001, 2, 125801, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 1, 322, 2, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 0, "クリア", 24001, 2, 126001, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 1, 323, 3, "んーと。\nこれ、あげる。\nはい", 0, "プレシア", 24001, 2, 126101, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 2, 324, 4, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 0, "リリ", 24001, 2, 125801, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 2, 325, 5, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 0, "クリア", 24001, 2, 126001, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 2, 326, 6, "お兄。\nきてくれて、うれしい", 0, "プレシア", 24001, 2, 126101, 1);
